+      id: `${eventType}:${userId}:${now}:${crypto.randomUUID()}`,
+      eventType,
+      actorPrincipalId: principal?.principalId ?? null,
+      subjectPrincipalId: principal?.principalId ?? null,
+      subjectUserId: userId,
+      metadata: JSON.stringify(metadata),
+      createdAt: now,
+    })
